#!/usr/bin/env bash\n# Test script for nightly-safehouse-s3-dynamo Terraform module\n# Mock rationale: we verify presence of required resource blocks without invoking Terraform.\n\nset -e\n\nMODULE_DIR="$(cd \"$(dirname \"${BASH_SOURCE[0]}\")/../src\" && pwd)"\n\n# Helper to assert a pattern exists in a file\nassert_in_file() {\n  local file=$1\n  local pattern=$2\n  if ! grep -qE "$pattern" "$file"; then\n    echo "FAIL: Expected pattern '$pattern' not found in $file"\n    exit 1\n  fi\n}\n\n# Check main.tf for S3 bucket resource\nassert_in_file "$MODULE_DIR/main.tf" "resource \"aws_s3_bucket\" \"safehouse\""\n\n# Check main.tf for DynamoDB table resource\nassert_in_file "$MODULE_DIR/main.tf" "resource \"aws_dynamodb_table\" \"logs\""\n\n# Check variables.tf for required variables\nassert_in_file "$MODULE_DIR/variables.tf" "variable \"bucket_name\""\nassert_in_file "$MODULE_DIR/variables.tf" "variable \"dynamodb_table_name\""\n\necho "All checks passed."\n
